}

func TestFlagWithDefaultVariant(t *testing.T) {
	f := &flipt.Flag{
		Key:          "flipt",
		Name:         "flipt",
		NamespaceKey: "flipt",
		Enabled:      false,
		DefaultVariant: &flipt.Variant{
			Key: "default-variant",
		},
